package org.apache.commons.compress.archivers.zip;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.EOFException;
import java.io.IOException;
import java.io.InputStream;
import java.io.PushbackInputStream;
import java.math.*;
import java.nio.ByteBuffer;
import java.util.*;
import java.util.zip.CRC32;
import java.util.zip.DataFormatException;
import java.util.zip.Inflater;
import java.util.zip.ZipEntry;
import java.util.zip.ZipException;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveInputStream;
import org.apache.commons.compress.utils.IOUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

public class ZipArchiveInputStream_ZipArchiveInputStream_TriageGen2Test {











    @Test
    public void testConstructorWithDifferentBooleanCombinations() throws IOException {
        byte[] dummyData = new byte[10];
        InputStream is = new ByteArrayInputStream(dummyData);

        // Test false, false
        ZipArchiveInputStream zais1 = new ZipArchiveInputStream(is, "UTF-8", false, false);
        assertNotNull(zais1);
        zais1.close();

        // Test true, false
        InputStream is2 = new ByteArrayInputStream(dummyData);
        ZipArchiveInputStream zais2 = new ZipArchiveInputStream(is2, "UTF-8", true, false);
        assertNotNull(zais2);
        zais2.close();

        // Test false, true
        InputStream is3 = new ByteArrayInputStream(dummyData);
        ZipArchiveInputStream zais3 = new ZipArchiveInputStream(is3, "UTF-8", false, true);
        assertNotNull(zais3);
        zais3.close();
    }


}

